function mintToken(uint256 _initialSupply, uint8 _tokenDecimal, uint _tokenNameLength, uint _tokenSymbolLength, bytes _name, bytes _symbol) public {
        totalSupply = _initialSupply * 10 ** uint256(_tokenDecimal);  
        balanceOf[msg.sender] = totalSupply;                
        name = _name;                                   
        symbol = _symbol;                               
    }
}

function freezeAccount(address target, bool freeze) onlyOwner public {
        frozenAccount[target] = freeze;
        FrozenFunds(target, freeze);
    }

function setPrices(uint256 newSellPrice, uint256 newBuyPrice) onlyOwner public {
        sellPrice = newSellPrice;
        buyPrice = newBuyPrice;
    }

function setExchange(bool isOpen) onlyOwner public {
        isOpened = isOpen;
    }

function buy() payable public {
        require(isOpened);
        uint amount = msg.value / buyPrice;               
        _transfer(this, msg.sender, amount);              
    }

function sell(uint256 amount) public {
        require(this.balance >= amount * sellPrice);      
        require(isOpened);
        _transfer(msg.sender, this, amount);              
        msg.sender.transfer(amount * sellPrice);          
    }

function mintPreSaleTokens(address target, uint256 mintedAmount) onlyOwner public {
        require(preSaleTokensRemaining[target] >= mintedAmount);
        require(preSaleTokensSold + mintedAmount <= preSaleMaxTokens);
        require(preSaleTokensSold + mintedAmount <= preSaleTokensRemaining[target]);
        preSaleTokensRemaining[target] -= mintedAmount;
        preSaleTokensSold += mintedAmount;
        preSaleTokensBought[target] += mintedAmount;
        Transfer(0, this, mintedAmount);
        Transfer(this, target, mintedAmount);
    }

function refundPreSaleTokens(address target) onlyOwner public {
        require(preSaleTokensSold > 0);
        require(preSaleTokensRefunded[target] == 0);
        uint256 refundAmount = preSaleTokensBought[target];
        preSaleTokensRefunded[target] = refundAmount;
        preSaleTokensBought[target] = 0;
        target.transfer(refundAmount * sellPrice);
        PreSaleTokensRefunded(target, refundAmount);
    }

function setPreSaleStartTime(uint256 newPreSaleStartTime) onlyOwner public {
        preSaleStartTime = newPreSaleStartTime;
    }

function setPreSaleEndTime(uint256 newPreSaleEndTime) onlyOwner public {
        preSaleEndTime = newPreSaleEndTime;
    }

function setPreSaleMaxTokens(uint256 newPreSaleMaxTokens) onlyOwner public {
        preSaleMaxTokens = newPreSaleMaxTokens;
    }

function setPreSaleMaxAmount(uint256 newPreSaleMaxAmount) onlyOwner public {
        preSaleMaxAmount = newPreSaleMaxAmount;
    }

function setPreSaleMinAmount(uint256 newPreSaleMinAmount) onlyOwner public {
        preSaleMinAmount = newPreSaleMinAmount;
    }

function setPreSaleTokensRemaining(address target, uint256 newPreSaleTokensRemaining) onlyOwner public {
        preSaleTokensRemaining[target] = newPreSaleTokensRemaining;
    }

function setPreSaleTokensSold(address target, uint256 newPreSaleTokensSold) onlyOwner public {
        preSaleTokensSold[target] = newPreSaleTokensSold;
    }

function setPreSaleTokensBought(address target, uint256 newPreSaleTokensBought) onlyOwner public {
        preSaleTokensBought[target] = newPreSaleTokensBought;
    }

function setPreSaleTokensRefunded(address target, uint256 newPreSaleTokensRefunded) onlyOwner public {
        preSaleTokensRefunded[target] = newPreSaleTokensRefunded;
    }
